/* MedicCare.module.css — faithful port of Medic Care (Templatemo 566) */

.root {
  /* Spine roles derived from original palette */
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #247cff;
  --vt-on-accent: #FFFFFF;
  --vt-accent-ink: #247cff;
  --vt-accent-on-deep: #247cff;
  --vt-line: #EAEAEA;

  font-family: 'Open Sans', sans-serif;
  background: var(--vt-surface);
  color: var(--vt-ink);
  padding-top: 94px;
}

.root a {
  color: var(--vt-ink-soft);
  text-decoration: none;
  transition: all 0.3s;
}

.root a:hover {
  color: var(--vt-accent);
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

/* ---------- Navigation ---------- */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  background: var(--vt-surface);
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
  z-index: 1000;
  padding-top: 20px;
  padding-bottom: 20px;
}

.navIn {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  display: inline-flex;
  align-items: center;
}

.brand {
  /* Brand handles its own inner styling */
  font-size: 24px;
  font-weight: 700;
  color: var(--vt-accent);
  text-align: center;
  line-height: 1.2;
}

.navLinks {
  display: flex;
  align-items: center;
  gap: 0;
}

.navLinks a {
  display: block;
  padding: 15px 1.5rem;
  font-size: 16px;
  font-weight: 600;
  color: var(--vt-ink-soft);
}

.navLinks a:hover {
  color: var(--vt-ink);
}

/* ---------- Hero ---------- */
.hero {
  position: relative;
  height: 580px;
  overflow: hidden;
}

.heroTrack {
  position: absolute;
  inset: 0;
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
}

.heroTrack::-webkit-scrollbar {
  display: none;
}

.slide {
  flex: 0 0 100%;
  scroll-snap-align: start;
  height: 100%;
  margin: 0;
}

.slideImg {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.heroCard {
  position: absolute;
  z-index: 2;
  bottom: 0;
  right: 0;
  width: 50%;
  background: var(--vt-surface);
  padding: 1.5rem 2.5rem;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.kicker {
  color: var(--vt-accent);
  font-size: 18px;
  font-weight: 600;
  margin: 0 0 0.5rem;
  letter-spacing: 0.5px;
}

.heroTitle {
  font-size: 48px;
  font-weight: 700;
  line-height: 1.2;
  color: var(--vt-ink);
  margin: 0 0 1rem;
}

.heroText {
  font-size: 18px;
  font-weight: 300;
  color: var(--vt-ink-soft);
  margin: 0 0 1.5rem;
  letter-spacing: 0.5px;
}

.heroLinks {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem;
}

.cta {
  display: inline-block;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  text-transform: uppercase;
  transition: all 0.3s;
}

.cta:hover {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border-color: var(--vt-accent);
}

.phone {
  font-weight: 600;
  color: var(--vt-ink-soft);
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
}

.phone i {
  color: var(--vt-accent);
  font-size: 1.2em;
}

/* ---------- Sections / Container ---------- */
.section {
  padding: 7rem 0;
}

.container {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
}

.sectionTitle {
  font-size: 36px;
  font-weight: 700;
  color: var(--vt-ink);
  margin-bottom: 1.5rem;
}

.center {
  text-align: center;
  margin-bottom: 3rem;
}

/* ---------- About ---------- */
.aboutGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  align-items: center;
}

.aboutContent {
  font-size: 18px;
  font-weight: 300;
  color: var(--vt-ink-soft);
  letter-spacing: 0.5px;
  line-height: 1.7;
}

.aboutText {
  margin-bottom: 1rem;
}

.storyFigure {
  margin: 0;
  display: flex;
  justify-content: center;
}

.storyImg {
  max-width: 100%;
  height: auto;
  border-radius: 0.25rem;
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
}

/* ---------- Gallery ---------- */
.gallery {
  padding: 0;
}

.galleryGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
}

.galleryItem {
  margin: 0;
  overflow: hidden;
}

.galleryImg {
  width: 100%;
  height: auto;
  display: block;
  transition: transform 0.3s ease;
}

.galleryItem:hover .galleryImg {
  transform: scale(1.05);
}

/* ---------- Timeline ---------- */
.timeline {
  position: relative;
  padding: 2rem 0;
}

.timeline::before {
  content: "";
  position: absolute;
  top: 37px;
  bottom: 0;
  left: 50%;
  width: 0;
  border-left: 1px solid var(--vt-line);
  transform: translateX(-50%);
}

.timelineNode {
  display: grid;
  grid-template-columns: 1fr 100px 1fr;
  align-items: start;
  margin: 2rem 0;
  position: relative;
}

.timelineIcon {
  grid-column: 2;
  grid-row: 1;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 80px;
  height: 80px;
  background: var(--vt-surface);
  border-radius: 50%;
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
  z-index: 2;
  margin: 0 auto;
}

.iconNumber {
  font-size: 32px;
  font-weight: 700;
  color: var(--vt-accent);
  line-height: 1;
}

.timelineCard {
  background: var(--vt-surface);
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
  border-radius: 0 0 0.25rem 0.25rem;
  padding: 0;
  position: relative;
}

.timelineTitle {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  border-radius: 0.25rem 0.25rem 0 0;
  position: relative;
  font-size: 26px;
  font-weight: 600;
  margin: 0;
}

.timelineDesc,
.timelineDuration {
  padding: 10px 30px;
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  letter-spacing: 0.5px;
  margin: 0;
}

.timelineDuration {
  font-weight: 600;
  color: var(--vt-ink);
  padding-bottom: 20px;
}

.odd .timelineCard {
  grid-column: 1;
  grid-row: 1;
  text-align: right;
}

.odd .timelineTitle::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translate(0, -50%);
  width: 0;
  border-left: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.even .timelineCard {
  grid-column: 3;
  grid-row: 1;
  text-align: left;
}

.even .timelineTitle::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translate(0, -50%);
  width: 0;
  border-right: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

/* ---------- Footer ---------- */
.footer {
  background: var(--vt-surface-2);
  padding: 7rem 0;
}

.footerGrid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 2rem;
}

.footerCol {
  font-size: 18px;
  font-weight: 300;
  color: var(--vt-ink-soft);
}

.footerTitle {
  font-size: 24px;
  font-weight: 600;
  color: var(--vt-ink);
  margin-bottom: 1.5rem;
}

.hours {
  margin: 0;
  line-height: 1.8;
  white-space: pre-line;
}

.socialLinks {
  margin: 0;
  padding: 0;
  list-style: none;
}

.socialLinks li {
  display: inline-block;
  margin-right: 15px;
}

.socialLinks a {
  font-size: 18px;
  color: var(--vt-ink-soft);
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
}

.socialLinks a:hover {
  color: var(--vt-accent);
}

.copyright {
  margin-top: 3rem;
  font-size: 16px;
  color: var(--vt-ink-soft);
  text-align: center;
}

/* ---------- Responsive ---------- */
@media screen and (min-width: 1600px) {
  .hero {
    height: 740px;
  }
}

@media screen and (max-width: 991px) {
  .root {
    padding-top: 74px;
  }

  .nav {
    padding-top: 10px;
    padding-bottom: 10px;
  }

  .navLinks a {
    padding: 5px 10px;
  }

  .heroTitle {
    font-size: 38px;
  }

  .sectionTitle {
    font-size: 32px;
  }

  .section {
    padding: 5rem 0;
  }

  .hero {
    height: auto;
  }

  .heroCard {
    position: relative;
    bottom: 100px;
    left: 0;
    width: auto;
    margin: -100px 0 0;
  }

  .timeline::before {
    top: 60px;
  }
}

@media screen and (max-width: 767px) {
  .heroCard {
    padding: 1.5rem;
  }

  .heroTitle {
    font-size: 32px;
  }

  .aboutGrid {
    grid-template-columns: 1fr;
  }

  .footerGrid {
    grid-template-columns: 1fr;
  }

  .timeline::before {
    top: 60px;
    left: 33px;
    transform: translateX(-50%);
  }

  .timelineNode {
    display: block;
    margin-left: 80px;
    position: relative;
  }

  .timelineIcon {
    position: absolute;
    left: -80px;
    top: 0;
  }

  .timelineCard {
    width: 100%;
    text-align: left !important;
  }

  .odd .timelineTitle::after,
  .even .timelineTitle::after {
    right: 100%;
    left: auto;
    border-left: 0;
    border-right: 10px solid var(--vt-surface-deep);
    border-top: 10px solid transparent;
    border-bottom: 10px solid transparent;
  }
}

@media screen and (max-width: 575px) {
  .timeline::before {
    left: 57px;
    top: 60px;
  }

  .timelineIcon {
    left: -10px;
    width: 70px;
    height: 70px;
  }

  .iconNumber {
    font-size: 26px;
  }

  .timelineNode {
    margin-left: 70px;
  }

  .timelineIcon {
    left: -70px;
  }
}

@media screen and (max-width: 480px) {
  .heroCard {
    padding: 1rem;
  }

  .heroLinks {
    gap: 0.5rem;
  }

  .cta {
    font-size: 12px;
    line-height: 30px;
    padding: 0 25px;
  }

  .phone {
    font-size: 12px;
  }
}

@media screen and (max-width: 360px) {
  .timeline::before {
    left: 42px;
  }

  .timelineIcon {
    width: 65px;
    height: 65px;
  }

  .iconNumber {
    font-size: 22px;
  }

  .timelineNode {
    margin-left: 65px;
  }

  .timelineIcon {
    left: -65px;
  }
}
